def agent_action(sandbox, agent_body, step_count):
    target = sandbox.get_target_speed()
    measured_speed = sandbox.get_wheel_angular_velocity()
    error = target - measured_speed
    current_speed_abs = abs(measured_speed)

    # Calculate maximum torque based on current speed
    max_torque = 3.5 + 15.5 * min(current_speed_abs, 3)

    if current_speed_abs < 0.3:
        # Wheel is stalled or near stall
        if error > 0:
            # Apply maximum torque to accelerate
            applied_torque = max_torque
        else:
            # No torque needed if target is lower
            applied_torque = 0.0
    else:
        # Proportional control with adaptive gain
        if current_speed_abs < 0.5:
            K = 3.0  # Higher gain for low-speed recovery
        else:
            K = 0.5  # Standard gain for normal operation

        desired_torque = K * error

        # Apply deadzone and torque limits
        if abs(desired_torque) < 2:
            applied_torque = 0.0
        else:
            applied_torque = min(desired_torque, max_torque)
            applied_torque = max(applied_torque, -max_torque)

    # Apply the calculated torque
    sandbox.apply_motor_torque(applied_torque)

